import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const output = "src/media-polish.css";
const sources = [
  "src/media-editorial.css",
  "src/visual-qa-refinement.css",
  "src/mobile-qa-final.css",
  "src/archive-character.css",
  "src/flagship-polish.css",
  "src/newsletter.css",
  "src/first-paint-polish.css"
];

const content = [
  "/* Generated by scripts/build-media-polish.mjs. Edit the source layers, then rebuild. */",
  ...sources.map(relative => {
    const css = fs.readFileSync(path.join(ROOT, relative), "utf8").trim();
    return `\n/* ${relative} */\n${css}`;
  }),
  ""
].join("\n");

fs.writeFileSync(path.join(ROOT, output), content);
console.log(`Media polish bundle built: ${sources.length} sources, ${Buffer.byteLength(content)} bytes.`);
